    /// <summary>
    /// A kernel for <see cref="Ops.AttentionScoresInt8"/>, given the device it runs on (<c>backend</c>) and the operation's arguments:
    /// y[r, t, c] = scales[r, c] · Σ_d q[r, t, d] · keys[r, c, d] for every cached position c.
    /// </summary>
