    /// <summary>
    /// A kernel for <see cref="Ops.AttentionContextInt8"/>, given the device it runs on (<c>backend</c>) and the operation's arguments:
    /// y[r, t, d] = Σ_c weights[r, t, c] · scales[r, c] · values[r, c, d].
    /// </summary>
