    /// </summary>
    public static readonly Operation PowBackward =
        new("PowBackward", "PowBackwardKernel", "Storage,Storage,Storage,Int32,Single", OperationIndex.PowBackward, typeof(OperationKernels.PowBackward), KernelSource.Host);

    /// <summary>
