        new("Axpy", "AxpyKernel", "Storage,Storage,Int32,Single", OperationIndex.Axpy, typeof(OperationKernels.Axpy), KernelSource.Host);

    /// <summary>
    /// c += a * b, element-wise.
    /// </summary>
