        new("MulAdd", "MulAddKernel", "Storage,Storage,Storage,Int32", OperationIndex.MulAdd, typeof(OperationKernels.MulAdd), KernelSource.Host);

    /// <summary>
    /// c[r, j] = a[r, j] + v[j].
    /// </summary>
